module tb;

    // Inputs declared as regs
    reg clk;
    reg reset;
    reg data;

    // Outputs declared as wires
    wire start_shifting;

    // Instantiate TopModule
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one bit of data and check expected output on the next cycle
    task apply_bit(input bit val, input bit expected_out);
        begin
            @(posedge clk);
            #1; // small delay to let signals settle after clock edge
            data = val;
            @(posedge clk);
            #1;
            if (start_shifting !== expected_out) begin
                $display("Mismatch at time %0t: data=%b, expected start_shifting=%b, got=%b", 
                         $time, val, expected_out, start_shifting);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Hold reset for a few cycles
        @(posedge clk);
        @(posedge clk);
        #1;

        // Check reset state
        if (start_shifting !== 1'b0) begin
            $display("Reset error: start_shifting is not 0 after reset.");
            errors = errors + 1;
        end

        // Deassert reset
        reset = 0;
        @(posedge clk);

        // Test Sequence 1: Incorrect sequence "1001" -> should not trigger
        $display("Applying sequence 1, 0, 0, 1 (should not trigger)");
        apply_bit(1'b1, 1'b0); // saw 1
        apply_bit(1'b0, 1'b0); // saw 10 -> back to IDLE
        apply_bit(1'b0, 1'b0); // saw 0 -> IDLE
        apply_bit(1'b1, 1'b0); // saw 1

        // Reset via synchronous reset test
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Synchronous reset error.");
            errors = errors + 1;
        end
        reset = 0;
        @(posedge clk);

        // Test Sequence 2: Correct sequence "1101" -> should trigger
        $display("Applying sequence 1, 1, 0, 1 (should trigger)");
        apply_bit(1'b1, 1'b0); // saw 1 (State: S_1)
        apply_bit(1'b1, 1'b0); // saw 11 (State: S_11)
        apply_bit(1'b0, 1'b0); // saw 110 (State: S_110)
        apply_bit(1'b1, 1'b1); // saw 1101 (State: S_DONE, start_shifting = 1)

        // Verify that start_shifting stays high forever once triggered, even with garbage data
        $display("Verifying start_shifting stays high permanently");
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b1, 1'b1);
        apply_bit(1'b0, 1'b1);

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
